-- migration_100_writing_task1_built_in.sql  (2026-11-05)
-- Mr Ikromov's 81 Writing Task 1 practice tests (each with its own graphic,
-- 20-minute timer and a check against the sample answer) are part of the
-- website: pages live in public/practice/writing/task1/<type folder>/.
-- This adds them to the Practice Bank under Writing, one set per type
-- (Change charts, Comparative graphs, Mixed graphs, Maps, Processes),
-- numbered by task (T1–T81).
-- The page's own check is a self-check for the student, not a mark: the
-- website saves no score for writing pages, the teacher marks the report.
-- Writing stays homework-only: these are never put on the students' shelf.
-- Safe to run twice. Needs migration 92 first.

insert into public.materials
  (title, file_name, storage_path, url, mime_type, size_bytes, source,
   skill, question_type, collection, position, on_shelf, created_by)
select v.title, v.file_name, 'site:' || substr(v.url, 2), v.url, 'text/html', v.size, 'upload',
       'writing', 'writing_task1', v.collection, v.pos, false, null
